"""Customer insight endpoints."""

from __future__ import annotations

from typing import Any

from orders.application.customer_service import CustomerService
from orders.application.errors import CustomerNotFound
from orders.application.order_service import OrderService
from orders.controllers.http import InvalidRequest, Response, bad_request, not_found, require_positive_int


class CustomerInsightsController:
    def __init__(self, order_service: OrderService, customer_service: CustomerService) -> None:
        self._order_service = order_service
        self._customer_service = customer_service

    def handle_order_history(self, customer_id: str) -> Response:
        try:
            orders = self._order_service.list_for_customer(customer_id)
        except CustomerNotFound:
            return not_found("customer")
        order_entries = []
        for order in reversed(orders):
            summary = self._order_service.summarize(order)
            order_entries.append({
                "order_id": order.order_id,
                "status": order.status,
                "total_cents": summary.total_cents,
            })
        return Response(200, {
            "customer_id": customer_id,
            "orders": order_entries,
        })

    def handle_lifetime_value(self, customer_id: str) -> Response:
        try:
            orders = self._order_service.list_for_customer(customer_id)
        except CustomerNotFound:
            return not_found("customer")
        order_count = 0
        lifetime_value_cents = 0
        for order in orders:
            if order.status != "cancelled":
                summary = self._order_service.summarize(order)
                order_count += 1
                lifetime_value_cents += summary.total_cents
        return Response(200, {
            "customer_id": customer_id,
            "order_count": order_count,
            "lifetime_value_cents": lifetime_value_cents,
        })

    def handle_top_customers(self, limit: Any) -> Response:
        try:
            limit_int = require_positive_int(limit, "limit")
        except InvalidRequest as exc:
            return bad_request(exc)
        customers = self._customer_service.list_all()
        customer_values = []
        for customer in customers:
            try:
                orders = self._order_service.list_for_customer(customer.customer_id)
            except CustomerNotFound:
                continue
            lifetime_value_cents = 0
            for order in orders:
                if order.status != "cancelled":
                    summary = self._order_service.summarize(order)
                    lifetime_value_cents += summary.total_cents
            if lifetime_value_cents > 0:
                customer_values.append({
                    "customer_id": customer.customer_id,
                    "name": customer.name,
                    "lifetime_value_cents": lifetime_value_cents,
                })
        customer_values.sort(key=lambda c: (-c["lifetime_value_cents"], c["customer_id"]))
        return Response(200, {
            "customers": customer_values[:limit_int],
        })

    def handle_customers_without_orders(self) -> Response:
        customers = self._customer_service.list_all()
        result = []
        for customer in customers:
            try:
                orders = self._order_service.list_for_customer(customer.customer_id)
            except CustomerNotFound:
                continue
            has_active_order = any(order.status != "cancelled" for order in orders)
            if not has_active_order:
                result.append({
                    "customer_id": customer.customer_id,
                    "name": customer.name,
                    "email": customer.email,
                })
        return Response(200, {
            "customers": result,
        })
